let playlistReplaceSelected=new Set(),playlistReplaceContext=null;
let selectedPlaylist='',playlistPageVersion=0,playlistEdit=null,playlistAI=null,playlistBusy=false,playlistTheme='',playlistCount=25,playlistJob='',playlistLastDraw='';
function playlistItems(list){const available=new Map(data.items.filter(i=>i.status==='ready'&&audioFormats.includes(i.format)).map(i=>[trackKey(i),i]));return list.tracks.map(key=>available.get(key)).filter(Boolean);}
async function playlistWrite(payload){const r=await fetch('/api/playlists',{method:'POST',headers:{'Content-Type':'application/json','X-Fieldstation':'playlists'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw Error(d.error||'Unable to save playlist');if(d.playlists){musicLists=d.playlists;videoOverrides=d.videoOverrides||{};}return d;}
async function renderPlaylistsPage(force=false){
 if(playlistEdit&&!force)return;
 const version=++playlistPageVersion;await loadMusicLists();if(version!==playlistPageVersion||view!=='playlists')return;
 const draw=JSON.stringify([selectedPlaylist,musicLists,data.items.length]);if(!force&&draw===playlistLastDraw)return;playlistLastDraw=draw;
 const root=$('#playlists-page'),list=musicLists.find(p=>p.id===selectedPlaylist);
 if(list){const songs=playlistItems(list);root.innerHTML='<button class="action" id="playlist-back">← All playlists</button><h2>'+esc(list.name)+'</h2><p>'+songs.length+' available tracks'+(songs.length!==list.tracks.length?' · '+(list.tracks.length-songs.length)+' unavailable':'')+'</p><div class="eq-actions"><button class="action" id="playlist-play" '+(!songs.length?'disabled':'')+'>▶ Play playlist</button><button class="action secondary" id="playlist-edit">Edit playlist</button>'+(list.id!=='favorites'?'<button class="action secondary" id="playlist-delete">Delete playlist</button>':'')+'</div><div style="margin-top:16px">'+songs.map((i,n)=>'<article class="row"><div class="row-text"><div class="row-title">'+(n+1)+'. '+esc(i.title)+'</div><div class="meta">'+esc(i.artist||'Unknown artist')+' · '+esc(i.album||'')+'</div></div><button class="action" data-playlist-track="'+esc(i.id)+'">Play</button></article>').join('')+'</div>';
 $('#playlist-back').onclick=()=>{selectedPlaylist='';renderPlaylistsPage(true)};$('#playlist-play').onclick=()=>playAudio(songs[0],songs);$('#playlist-edit').onclick=()=>editPlaylist(list);$('#playlist-delete')?.addEventListener('click',()=>deletePlaylist(list));root.querySelectorAll('[data-playlist-track]').forEach(b=>b.onclick=()=>playAudio(songs.find(i=>i.id===b.dataset.playlistTrack),songs));return;
 }
 root.innerHTML='<div class="eq-actions"><p>Choose a mix, or create one around a mood, moment or musical theme.</p><button class="action secondary" id="playlist-new">Create playlist manually</button></div><div class="tiles">'+musicLists.map(p=>{const songs=playlistItems(p);return '<article class="spotify-card playlist-browse-card"><div class="playlist-art" aria-hidden="true">'+categoryGraphic(p.name.includes('Classical')?'Classical':p.name.includes('World')||p.name.includes('Asian')?'World & Asian':p.name.includes('Rock')||p.name.includes('Energy')?'Rock':p.name.includes('Musical')||p.name.includes('Stage')?'Soundtracks & Stage':p.id==='favorites'?'Pop':'Music Videos & Concerts')+'</div><h2>'+esc(p.name)+'</h2><p>'+songs.length+' tracks</p><div class="eq-actions"><button class="action" data-play-list="'+esc(p.id)+'" '+(!songs.length?'disabled':'')+'>▶ Play</button><button class="action" data-view-list="'+esc(p.id)+'">View songs</button><button class="action secondary" data-edit-list="'+esc(p.id)+'">Edit</button>'+(p.id!=='favorites'?'<button class="action secondary" data-delete-list="'+esc(p.id)+'">Delete</button>':'')+'</div></article>';}).join('')+'</div><section class="spotify-card playlist-generator"><h2>Create a playlist with AI</h2><p>Describe the mood, genre, occasion or era. Codex will choose from music already on your SSD.</p><form id="playlist-generate"><label for="playlist-theme">Your theme</label><textarea id="playlist-theme" maxlength="600" minlength="3" required rows="3" placeholder="e.g. Rainy evening jazz, mellow piano and a few soulful vocals">'+esc(playlistTheme)+'</textarea><div class="eq-actions"><label>Tracks <select id="playlist-count">'+[10,15,25,40,50].map(n=>'<option '+(n===playlistCount?'selected':'')+'>'+n+'</option>').join('')+'</select></label><button class="action" id="playlist-generate-button" '+(playlistBusy?'disabled':'')+'>'+(playlistBusy?'Generating…':'Generate preview')+'</button></div></form><p class="meta">Requires internet and Codex sign-in. Your theme and music catalogue metadata are sent to OpenAI using your Codex account. Audio files stay on the SSD.</p><p id="playlist-ai-status" role="status"></p><div id="playlist-ai-preview"></div></section>';
 $('#playlist-new').onclick=()=>editPlaylist({id:'',name:'New playlist',tracks:[]});
 for(const [attr,fn] of [['viewList',p=>{selectedPlaylist=p.id;renderPlaylistsPage(true)}],['editList',editPlaylist],['deleteList',deletePlaylist],['playList',p=>{const songs=playlistItems(p);if(songs.length)playAudio(songs[0],songs)}]])root.querySelectorAll('[data-'+attr.replace(/[A-Z]/g,c=>'-'+c.toLowerCase())+']').forEach(b=>b.onclick=()=>fn(musicLists.find(p=>p.id===b.dataset[attr])));
 $('#playlist-theme').oninput=e=>{playlistTheme=e.target.value};$('#playlist-count').onchange=e=>{playlistCount=Number(e.target.value)};$('#playlist-generate').onsubmit=e=>{e.preventDefault();generatePlaylist()};drawPlaylistAI();renderCategoryAI();
}
async function deletePlaylist(list){if(!confirm('Delete “'+list.name+'”? This removes only the playlist. Music files stay on the SSD.'))return;try{await playlistWrite({action:'delete',playlist:list.id,revision:list.revision});if(selectedPlaylist===list.id)selectedPlaylist='';renderPlaylistsPage(true)}catch(e){alert(e.message)}}
function editPlaylist(list){playlistReplaceSelected.clear();playlistReplaceContext=null;playlistEdit={...list,tracks:[...list.tracks]};const root=$('#playlists-page');root.innerHTML='<h2>Edit playlist</h2><label>Playlist name <input id="playlist-edit-name" maxlength="80" value="'+esc(list.name)+'"></label><p>Move tracks with the arrows, remove them, or search your library to add more. Changes apply when you save.</p><div class="eq-actions"><button class="action" id="playlist-save">Save playlist</button><button class="action secondary" id="playlist-cancel">Cancel</button></div><p id="playlist-edit-error" role="status"></p><div class="spotify-card"><label>Theme for replacements <input id="playlist-replace-theme" maxlength="600" value="'+esc(list.name)+'"></label><p>Select the songs below that you want to replace. Other songs stay in their existing positions.</p><button class="action secondary" id="playlist-replace">Suggest replacements for selected songs</button><div id="playlist-replacements" aria-live="polite"></div></div><div id="playlist-edit-tracks"></div><h3>Add music</h3><label class="search"><input id="playlist-add-query" type="search" placeholder="Search song, artist or album" aria-label="Search music to add"></label><div id="playlist-add-results"></div>';
 $('#playlist-replace').onclick=replacePlaylistSongs;
 $('#playlist-edit-name').oninput=e=>playlistEdit.name=e.target.value;$('#playlist-cancel').onclick=()=>{playlistEdit=null;playlistReplaceContext=null;playlistAI=null;renderPlaylistsPage(true)};$('#playlist-save').onclick=async()=>{const b=$('#playlist-save');b.disabled=true;try{const d=await playlistWrite({action:playlistEdit.id?'update':'create',playlist:playlistEdit.id,revision:playlistEdit.revision,name:playlistEdit.name,tracks:playlistEdit.tracks});selectedPlaylist=playlistEdit.id||d.created_id;playlistEdit=null;playlistReplaceContext=null;playlistAI=null;renderPlaylistsPage(true)}catch(e){$('#playlist-edit-error').textContent=e.message;b.disabled=false}};$('#playlist-add-query').oninput=drawPlaylistAdd;drawPlaylistEdit();drawPlaylistAdd();
}
function playlistTrackMap(){return new Map(data.items.filter(i=>i.status==='ready'&&audioFormats.includes(i.format)).map(i=>[trackKey(i),i]));}
function drawPlaylistEdit(){const map=playlistTrackMap();$('#playlist-edit-tracks').innerHTML=playlistEdit.tracks.map((k,n)=>{const t=map.get(k);return '<article class="row"><input type="checkbox" data-replace-key="'+n+'" aria-label="Select track '+(n+1)+' for replacement" '+(playlistReplaceSelected.has(k)?'checked':'')+'><div class="row-text"><strong>'+(n+1)+'. '+esc(t?t.title:k.split('|').at(-1))+'</strong><div class="meta">'+esc(t?t.artist||'Unknown artist':'Unavailable file')+'</div></div><div class="eq-actions"><button class="action secondary" data-move="'+n+'" data-step="-1" aria-label="Move track '+(n+1)+' up" '+(!n?'disabled':'')+'>↑</button><button class="action secondary" data-move="'+n+'" data-step="1" aria-label="Move track '+(n+1)+' down" '+(n===playlistEdit.tracks.length-1?'disabled':'')+'>↓</button><button class="action secondary" data-remove="'+n+'">Remove</button></div></article>'}).join('')||'<p>No tracks yet. Search below to add some.</p>';
 $('#playlist-edit-tracks').querySelectorAll('[data-replace-key]').forEach(b=>b.onchange=()=>{const k=playlistEdit.tracks[Number(b.dataset.replaceKey)];if(b.checked)playlistReplaceSelected.add(k);else playlistReplaceSelected.delete(k)});
 $('#playlist-edit-tracks').querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{playlistEdit.tracks.splice(Number(b.dataset.remove),1);drawPlaylistEdit();drawPlaylistAdd()});$('#playlist-edit-tracks').querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.move),to=n+Number(b.dataset.step);[playlistEdit.tracks[n],playlistEdit.tracks[to]]=[playlistEdit.tracks[to],playlistEdit.tracks[n]];drawPlaylistEdit()});
}
function drawPlaylistAdd(){const q=$('#playlist-add-query').value.toLowerCase().trim(),all=[...playlistTrackMap()].filter(([k,t])=>!playlistEdit.tracks.includes(k)&&(!q||(t.title+' '+(t.artist||'')+' '+(t.album||'')).toLowerCase().includes(q))),items=all.slice(0,25);$('#playlist-add-results').innerHTML='<p class="meta">'+all.length+' matches · showing up to 25</p>'+items.map(([k,t],n)=>'<article class="row"><div class="row-text"><strong>'+esc(t.title)+'</strong><div class="meta">'+esc(t.artist||'Unknown artist')+' · '+esc(t.album||'')+'</div></div><button class="action" data-add="'+n+'">Add</button></article>').join('');$('#playlist-add-results').querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{if(playlistEdit.tracks.length>=500){$('#playlist-edit-error').textContent='Maximum 500 tracks per playlist';return}playlistEdit.tracks.push(items[Number(b.dataset.add)][0]);drawPlaylistEdit();drawPlaylistAdd()});}
async function generatePlaylist(){if(playlistBusy)return;playlistReplaceContext=null;playlistBusy=true;playlistAI=null;drawPlaylistAI();try{const d=await playlistWrite({action:'generate',theme:playlistTheme,count:playlistCount});playlistJob=d.id;sessionStorage.setItem('playlist-ai-job',playlistJob);pollPlaylistAI()}catch(e){playlistBusy=false;playlistAI={state:'error',message:e.message};drawPlaylistAI()}}
async function pollPlaylistAI(){try{const r=await fetch('/api/playlist-ai?id='+encodeURIComponent(playlistJob));if(!r.ok)throw Error('Could not check generation progress');playlistAI=await r.json();playlistBusy=playlistAI.state==='running';drawPlaylistAI();if(playlistBusy)setTimeout(pollPlaylistAI,2000);else sessionStorage.removeItem('playlist-ai-job')}catch(e){playlistBusy=false;playlistAI={state:'error',message:e.message};drawPlaylistAI()}}
function drawPlaylistAI(){if(playlistReplaceContext){drawPlaylistReplacements();return;}if(!$('#playlist-ai-status'))return;$('#playlist-generate-button').disabled=playlistBusy;$('#playlist-generate-button').textContent=playlistBusy?'Generating…':'Generate preview';$('#playlist-ai-status').textContent=playlistAI?.message||(playlistBusy?'Starting Codex…':'Preview the selection before saving.');const root=$('#playlist-ai-preview');root.replaceChildren();if(playlistAI?.state!=='ready')return;root.innerHTML='<h3>'+esc(playlistAI.name)+'</h3><p>'+esc(playlistAI.explanation)+'</p><p>'+playlistAI.tracks.length+' tracks selected</p><ol>'+playlistAI.tracks.map(t=>'<li>'+esc(t.title)+' — '+esc(t.artist||'Unknown artist')+'</li>').join('')+'</ol><button class="action" id="playlist-use-draft">Review & save this playlist</button>';$('#playlist-use-draft').onclick=()=>editPlaylist({id:'',name:playlistAI.name,tracks:playlistAI.tracks.map(t=>t.key)});}
playlistJob=sessionStorage.getItem('playlist-ai-job')||'';if(playlistJob){playlistBusy=true;pollPlaylistAI()}

async function replacePlaylistSongs(){
 if(playlistBusy)return;const selected=playlistEdit.tracks.filter(k=>playlistReplaceSelected.has(k));if(!selected.length){$('#playlist-edit-error').textContent='Select at least one song to replace.';return}if(selected.length>50){$('#playlist-edit-error').textContent='Replace up to 50 songs at a time.';return}
 playlistReplaceContext={editor:playlistEdit,selected};playlistBusy=true;playlistAI=null;drawPlaylistReplacements();
 try{const d=await playlistWrite({action:'generate',theme:$('#playlist-replace-theme').value||playlistEdit.name,count:selected.length,exclude:[...playlistEdit.tracks]});playlistJob=d.id;pollPlaylistAI()}catch(e){playlistBusy=false;playlistAI={state:'error',message:e.message};drawPlaylistReplacements()}
}
function drawPlaylistReplacements(){
 const root=$('#playlist-replacements');if(!root||playlistEdit!==playlistReplaceContext?.editor)return;
 $('#playlist-replace').disabled=playlistBusy;$('#playlist-save').disabled=playlistBusy;$('#playlist-cancel').disabled=playlistBusy;root.textContent=playlistAI?.message||'Finding alternatives…';if(playlistAI?.state!=='ready')return;
 const map=playlistTrackMap(),old=playlistReplaceContext.selected;
 root.innerHTML='<p>'+esc(playlistAI.explanation)+'</p><ol>'+playlistAI.tracks.map((t,n)=>'<li>'+esc(map.get(old[n])?.title||'Selected track')+' → <strong>'+esc(t.title)+'</strong> — '+esc(t.artist)+'</li>').join('')+'</ol><p>Only these '+playlistAI.tracks.length+' selected slots will change. Save the playlist after applying.</p><button class="action" id="playlist-apply-replacements">Apply these replacements</button>';
 $('#playlist-apply-replacements').onclick=()=>{if(old.some(k=>!playlistEdit.tracks.includes(k))||playlistAI.tracks.some(t=>playlistEdit.tracks.includes(t.key))){root.textContent='The track list changed. Request fresh suggestions before applying.';return}playlistAI.tracks.forEach((t,n)=>{const i=playlistEdit.tracks.indexOf(old[n]);playlistEdit.tracks[i]=t.key});playlistReplaceSelected.clear();playlistReplaceContext=null;playlistAI=null;root.textContent='Replacements applied to your draft. Save when ready.';drawPlaylistEdit();drawPlaylistAdd()};
}

let categoryAIPending=false;
function renderCategoryAI(){
 const panel=document.createElement('section');panel.id='category-ai-panel';panel.className='spotify-card';panel.innerHTML='<h2>Category Top 10s</h2><p>AI selects up to 10 well-known songs for each music category from your current SSD library. Regenerating replaces only these category playlists; your other playlists and Favorites stay intact.</p><button class="action" id="category-ai-regenerate">Regenerate category Top 10s</button><p class="meta">Requires internet and Codex sign-in. Sends song metadata to OpenAI, never audio files. Picks are editorial selections, not live chart rankings.</p><p id="category-ai-progress" role="status"></p>';
 $('#playlists-page').append(panel);$('#category-ai-regenerate').onclick=async()=>{const b=$('#category-ai-regenerate');b.disabled=true;try{const r=await fetch('/api/playlists',{method:'POST',headers:{'Content-Type':'application/json','X-Fieldstation':'playlists'},body:JSON.stringify({action:'generate_categories'})});const d=await r.json();if(!r.ok)throw Error(d.error);paintCategoryAI(d);}catch(e){$('#category-ai-progress').textContent=e.message;b.disabled=false;}};pollCategoryAI();
}
function paintCategoryAI(d){const b=$('#category-ai-regenerate'),p=$('#category-ai-progress');if(!b||!p)return;b.disabled=d.state==='running';p.textContent=d.message+(d.total?' ('+d.completed+'/'+d.total+')':'')+(d.errors?.length?' '+d.errors.join(' · '):'');}
async function pollCategoryAI(){if(categoryAIPending||!$('#category-ai-panel')||$('#playlists-page').hidden)return;categoryAIPending=true;try{const d=await(await fetch('/api/category-playlists')).json();paintCategoryAI(d);if(d.state!=='running')await loadMusicLists();}catch{if($('#category-ai-progress'))$('#category-ai-progress').textContent='Unable to read category generation status.';}finally{categoryAIPending=false;}}
setInterval(pollCategoryAI,4000);
